# owner: platform
"""Lay students out in seating rows."""

from typing import List, Sequence

from rosterkit.models import Student

def _sort_key(student: Student) -> tuple:
    last = student.last_name.casefold()
    return (last, student.first_name.casefold())

def _check_inputs(students: Sequence, width: int) -> None:
    if width <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")

def _row_text(number: int, chunk: Sequence[Student]) -> str:
    names = [pupil.display_name for pupil in chunk]
    return f"Row {number}: " + " | ".join(names)

def _format_rows(ordered: Sequence[Student], width: int):
    starts = range(0, len(ordered), width)
    lines = []
    for index, start in enumerate(starts, 1):
        chunk = ordered[start:start + width]
        lines.append(_row_text(index, chunk))
    return lines

# ---
def seating_rows(
    students: Sequence[Student],
    seats_per_row: int,
) -> List[str]:
    """One text line per row, sorted by last name."""
    _check_inputs(students, seats_per_row)
    ordered = sorted(students, key=_sort_key)
    return _format_rows(ordered, seats_per_row)

