# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows

SPLIT_LINES = [
    "Row 1: Arden, Zoe | Dunmere, Piet",
    "Row 2: Halloway, Juno",
]

def make_student(last, first):
    ident = f"{last}-{first}"
    return Student(ident, last, first, "A")

class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.pupils = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Arden", "Zoe"),
        ]

    def test_sorted_by_last_name_and_split(self):
        lines = seating_rows(self.pupils, 2)
        self.assertEqual(lines, SPLIT_LINES)

    def test_single_row_when_seats_exceed_students(self):
        lines = seating_rows(self.pupils, 10)
        self.assertEqual(len(lines), 1)
        self.assertTrue(lines[0].startswith("Row 1: Arden"))

    def test_sort_ignores_case(self):
        pupils = [
            make_student("zane", "Amy"),
            make_student("Yost", "Bob"),
        ]
        lines = seating_rows(pupils, 5)
        self.assertEqual(
            lines, ["Row 1: Yost, Bob | zane, Amy"]
        )

    def test_same_last_name_orders_by_first(self):
        pupils = [
            make_student("Reed", "Tom"),
            make_student("Reed", "Ann"),
        ]
        lines = seating_rows(pupils, 2)
        self.assertEqual(
            lines, ["Row 1: Reed, Ann | Reed, Tom"]
        )

    def test_input_list_is_not_reordered(self):
        before = list(self.pupils)
        seating_rows(self.pupils, 2)
        self.assertEqual(self.pupils, before)

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.pupils, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.pupils, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 4)

if __name__ == "__main__":
    unittest.main()
